/**
 * nexus-browser-local — the hosted nexus-browser MCP, run locally over stdio. Add to Claude Code:
 *   claude mcp add nexus-browser-local -- node <path>/dist/server.js
 */
import './stdio-guard.js';   // FIRST: stdout carries only the MCP protocol (see stdio-guard.ts)
import { StdioServerTransport } from '@modelcontextprotocol/sdk/server/stdio.js';
import { createLocalBrowserMCP } from './local.js';

const mcp = await createLocalBrowserMCP();
const shutdown = async () => { await mcp.close(); process.exit(0); };
process.on('SIGINT', shutdown); process.on('SIGTERM', shutdown); process.stdin.on('end', shutdown);
await mcp.server.connect(new StdioServerTransport());
