/**
 * stdout carries the MCP protocol and nothing else: every console channel goes to stderr. Imported FIRST by server.ts (ES modules run in
 * import order), so it is in place before the bundled Worker code loads. Without it, any log line from that code or from nexus-cortex
 * core (imported at runtime for the secrets vault; it logs when DEBUG=true) corrupts the stream — 2026-11-03: a harness running with
 * DEBUG=true got "Unexpected token 'A', "AdapterReg"... is not valid JSON" from this server.
 */
for (const k of ['log', 'info', 'debug', 'warn'] as const) console[k] = (...a: unknown[]) => console.error(...a);
export {};
